<?php declare(strict_types=1);require_once __DIR__.'/../includes/admin-auth.php';$id=sanitize($_GET['id']??'');$release=release_by_id($id);if(!$release){http_response_code(404);fail('Release not found.');}$error='';$success='';if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$version=trim((string)($_POST['version']??''));$title=trim((string)($_POST['title']??''));$description=trim((string)($_POST['description']??''));$notes=array_values(array_filter(array_map('trim',(array)($_POST['release_notes']??[]))));$architecture=trim((string)($_POST['architecture']??'64-bit'));$supportedOs=trim((string)($_POST['supported_os']??'Windows 10 / 11'));if(!$version||!preg_match('/^\d+\.\d+\.\d+$/',$version))$error='Use a semantic version.';elseif(!$title||strlen($title)<3)$error='Add a release title.';elseif(!$description||strlen($description)<10)$error='Add a release description.';elseif(!$notes)$error='Add at least one release note.';else{$updates=['version'=>$version,'title'=>$title,'description'=>$description,'release_notes'=>$notes,'architecture'=>$architecture,'supported_os'=>$supportedOs];$updated=update_json('releases.json',fn($list)=>array_map(fn($r)=>is_array($r)&&($r['id']??'')===$id?array_merge($r,$updates):$r,$list));if($updated)$success='Release updated.';else$error='The release could not be saved.';}}?>
